1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import {
5|  AMBIENCES,
6|  DEFAULT_AMBIENCE_VOLUME,
7|  ambienceLabel,
8|  levelById,
9|  nextLevel,
10|} from "@/core/ambience";
11|import { loadAmbiencePrefs, saveAmbiencePrefs } from "./ambience-prefs";
12|import { AmbienceController } from "./ambience-controller";
13|import { WebAmbienceEngine } from "./ambience-engine";
14|
15|const RAIN = AMBIENCES[0]!;
16|
17|// One drop cycle: how long the button replays its animation after a click.
18|const ANIM_MS = 1400;
19|
20|const DROPS: Record<string, Array<[number, number]>> = {
21|  drizzle: [
22|    [7.5, 14.2],
23|    [10, 14.2],
24|    [12.5, 14.2],
25|  ],
26|  moderate: [
27|    [6.5, 13.8],
28|    [10, 13.8],
29|    [13.5, 13.8],
30|    [6.5, 15.9],
31|    [10, 15.9],
32|    [13.5, 15.9],
33|  ],
34|  storm: [
35|    [6, 14],
36|    [8, 14],
37|    [13.5, 14],
38|    [15.5, 14],
39|    [6, 16.2],
40|  ],
41|};
42|
43|// The button owns its controller: it loads prefs once, saves on change,
44|// and starts the stored level on the first gesture anywhere in the page.
45|export function RainAmbience({ muted }: { muted: boolean }) {
46|  const controllerRef = useRef<AmbienceController | null>(null);
47|  const [level, setLevel] = useState("off");
48|  const [volume, setVolume] = useState(DEFAULT_AMBIENCE_VOLUME);
49|  const [burst, setBurst] = useState(0);
50|  const burstTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
51|
52|  useEffect(() => {
53|    const controller = new AmbienceController(new WebAmbienceEngine());
54|    controllerRef.current = controller;
55|    const prefs = loadAmbiencePrefs();
56|    if (prefs) {
57|      controller.setVolume(prefs.volume);
58|      setVolume(prefs.volume);
59|      if (prefs.level !== "off" && levelById(RAIN, prefs.level)) {
60|        controller.setLevel(prefs.level);
61|        setLevel(prefs.level);
62|      }
63|    }
64|    const unlock = () => void controller.unlock();
65|    document.addEventListener("pointerdown", unlock, { once: true });
66|    document.addEventListener("keydown", unlock, { once: true });
67|    return () => {
68|      document.removeEventListener("pointerdown", unlock);
69|      document.removeEventListener("keydown", unlock);
70|      controller.dispose();
71|      controllerRef.current = null;
72|    };
73|  }, []);
74|
75|  useEffect(() => {
76|    controllerRef.current?.setMuted(muted);
77|  }, [muted]);
78|
79|  useEffect(
80|    () => () => {
81|      if (burstTimer.current) clearTimeout(burstTimer.current);
82|    },
83|    [],
84|  );
85|
86|  function cycle() {
87|    const controller = controllerRef.current;
88|    if (!controller) return;
89|    void controller.unlock();
90|    const id = nextLevel(RAIN, level);
91|    controller.setLevel(id);
92|    setLevel(id);
93|    saveAmbiencePrefs({ level: id, volume });
94|    setBurst((b) => b + 1);
95|    if (burstTimer.current) clearTimeout(burstTimer.current);
96|    burstTimer.current = setTimeout(() => setBurst(0), ANIM_MS);
97|  }
98|
99|  function changeVolume(value: number) {
100|    controllerRef.current?.setVolume(value);
101|    setVolume(value);
102|    saveAmbiencePrefs({ level, volume: value });
103|  }
104|
105|  const label = ambienceLabel(RAIN, level);
106|  return (
107|    <>
108|      <button
109|        type="button"
110|        className="skip rain"
111|        data-level={level}
112|        data-anim={burst ? "1" : undefined}
113|        onClick={cycle}
114|        aria-label={label}
115|        title={label}
116|      >
117|        {/* key replays the one-shot animation on rapid clicks */}
118|        <svg
119|          key={burst}
120|          width="20"
121|          height="20"
122|          viewBox="0 0 20 20"
123|          aria-hidden="true"
124|        >
125|          <path
126|            className="rain-cloud"
127|            d="M14.5 12.2h-8.3a3.4 3.4 0 0 1-.6-6.7 4.6 4.6 0 0 1 9-1.1 3 3 0 0 1-.1 7.8z"
128|            strokeLinejoin="round"
129|          />
130|          {(DROPS[level] ?? []).map(([x, y], i) => (
131|            <line
132|              key={i}
133|              className="rain-drop"
134|              x1={x}
135|              y1={y}
136|              x2={x}
137|              y2={y + (level === "drizzle" ? 1.8 : 1.5)}
138|            />
139|          ))}
140|          {level === "storm" ? (
141|            <polygon
142|              className="rain-bolt"
143|              points="11.3,13.4 9.3,16.2 10.6,16.2 10,18.8 12.5,15.6 11.2,15.6"
144|              fill="#f2c230"
145|              stroke="none"
146|            />
147|          ) : null}
148|        </svg>
149|      </button>
150|      {level !== "off" ? (
151|        <input
152|          type="range"
153|          className="rain-volume"
154|          min={0}
155|          max={1}
156|          step={0.05}
157|          value={volume}
158|          onChange={(e) => changeVolume(Number(e.target.value))}
159|          aria-label="Rain volume"
160|        />
161|      ) : null}
162|    </>
163|  );
164|}

