6|
7|export type MusicStyleControlProps = {
8|  modes: MusicMode[];
9|  current: MusicModeId | null;
10|  onAdvance: (to?: MusicModeId) => void;
11|};
12|
13|function stickerFor(id: string, label: string): string {
14|  return /piano/i.test(id) || /piano/i.test(label)
15|    ? "/art/stickers/piano.svg"
16|    : "/art/stickers/violin.svg";
17|}
