19|export function MusicStyleControl({ modes, current, onAdvance }: MusicStyleControlProps) {
20|  const styles = modes.filter((m) => m.kind === "style");
21|  const playlist = modes.find((m) => m.kind === "playlist") ?? null;
22|  return (
23|    <>
24|      {styles.length >= 2 ? (
25|        <span className="stickers" role="group" aria-label="Music style">
26|          {styles.map((s) => (
27|            <span className="sticker-wrap" key={s.id}>
28|              <button
29|                type="button"
30|                className="sticker"
31|                onClick={() => onAdvance(s.id)}
32|                aria-pressed={current === s.id}
33|                aria-label={s.label}
34|                title={s.label}
35|              >
36|                <img src={stickerFor(s.id, s.label)} alt="" width={40} height={40} />
37|              </button>
38|              <span className="sticker-dot" aria-hidden="true" />
39|            </span>
40|          ))}
41|        </span>
42|      ) : null}
43|      {playlist !== null ? (
44|        <button
45|          type="button"
46|          className="chopin"
47|          onClick={() => onAdvance(playlist.id)}
48|          aria-pressed={current === playlist.id}
49|          aria-label="Just play Chopin"
50|          title="Just play Chopin"
51|        >
52|          <img
53|            src="/art/chopin-just-play-me.png"
54|            alt="Just play Chopin"
55|            width={40}
56|            height={40}
57|          />
58|        </button>
59|      ) : null}
60|    </>
61|  );
